import sys,json
d=json.load(sys.stdin)
want={'AJC.picrep','AJC.picrep.divzero','AJC.picrep.assembly','AJC.picrep.divlocallyclosed','AJC.picrep.tensor','AJC.picrep.etale-rep','AJC.picrep.etale-rep.descent-assembly','AJC.picrep.divgrassmannian'}
def walk(n):
    if n.get('id') in want:
        print('=== ', n.get('id'),'| status',n.get('status'),'| owner',n.get('owner') or '-')
        print('  detail:', (n.get('detail') or '')[:300])
        print('  strategy:', (n.get('strategy') or n.get('notes') or '')[:500])
    for c in n.get('children',[]): walk(c)
items = d if isinstance(d,list) else d.get('items',[d])
for it in items: walk(it)
"
